<?php $title='My orders';require 'includes/header.php';require_login();if(isset($_GET['cancel'])){$q=$pdo->prepare("UPDATE orders SET status='Cancelled' WHERE id=? AND user_id=? AND status='Pending'");$q->execute([(int)$_GET['cancel'],$_SESSION['user']['id']]);$_SESSION['flash']='Order cancellation requested.';header('Location: '.url('orders.php'));exit;}$q=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$q->execute([$_SESSION['user']['id']]);$orders=$q->fetchAll(); ?>
<?php if(isset($_GET['success'])):?><div class="alert alert-success"><strong>Thank you!</strong> Your order has been placed successfully. Your invoice number is <strong><?=e($pdo->query('SELECT order_no FROM orders WHERE id='.(int)$_GET['success'])->fetchColumn())?></strong>.</div><?php endif;?><h1 class="section-title mb-4">My orders</h1><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Order ID</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td class="fw-bold"><?=e($o['order_no'])?></td><td><?=date('d M Y',strtotime($o['created_at']))?></td><td><?=money($o['total'])?></td><td><?=e($o['payment_method'])?></td><td><span class="badge bg-<?=in_array($o['status'],['Delivered'])?'success':($o['status']==='Cancelled'?'danger':'warning')?>"><?=e($o['status'])?></span></td><td><?php if($o['status']==='Pending'):?><a class="btn btn-sm btn-outline-danger" href="<?=url('orders.php?cancel='.$o['id'])?>">Cancel</a><?php endif;?></td></tr><?php endforeach;if(!$orders):?><tr><td colspan="6" class="text-center py-4 text-muted">No orders yet.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php'; ?>
